/*
 * A147882  Positive integers k that are balanced, meaning that if k has d
 *          digits, then its initial ceiling(d/2) digits have the same sum as
 *          its last ceiling(d/2) digits.
 * https://oeis.org/A147882
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = nth balanced integer (generated by brute‑force search)
 * Range:     u8 n <= 34, u16 n <= 4744, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>

/*
 * Helper that checks whether a number is balanced:
 *  For a d‑digit number, let t = floor(d/2).
 *  Sum of the t most significant digits must equal sum of the t least
 *  significant digits.  For odd d the middle digit is ignored.
 */
static bool is_balanced(seq_t x) {
    /* Extract digits from least significant to most significant. */
    unsigned char digits[64];   /* accommodates far beyond the needed size */
    size_t d = 0;
    seq_t tmp = x;
    while (tmp > 0) {
        digits[d++] = (unsigned char)(tmp % 10);
        tmp /= 10;
    }
    /* If x is 0, it is considered balanced (not used in this sequence). */
    if (d == 0) return true;

    size_t half = d / 2;          /* floor(d/2) */
    int sum_first = 0, sum_last = 0;
    for (size_t i = 0; i < half; ++i)
        sum_last += digits[i];           /* least significant digits */
    for (size_t i = 0; i < half; ++i)
        sum_first += digits[d - 1 - i];   /* most significant digits */
    return sum_first == sum_last;
}

/*
 * Cache of already generated balanced numbers.
 * The sequence is generated on demand until the requested index
 * has been reached.  Subsequent calls continue from where the
 * previous call left off, allowing any call order.
 */
static seq_t *cache = NULL;
static size_t cache_sz = 0;
static size_t cache_cap = 0;
static idx_t next_candidate = 1;   /* next integer to test for balance */

/* Result function */
seq_t a(idx_t n) {
    /* Lazy initialization of cache */
    if (cache == NULL) {
        cache_cap = 64;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
    }

    /* Generate numbers until we have at least n terms */
    while (cache_sz < n) {
        seq_t val = (seq_t)next_candidate;  /* convert to seq_t type */
        if (is_balanced(val)) {
            if (cache_sz >= cache_cap) {
                cache_cap *= 2;
                cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
            }
            cache[cache_sz++] = val;
        }
        ++next_candidate;
    }

    return cache[n - 1];   /* array is 0‑based, n is 1‑based */
}
